    return {
        "version": 1,
        "hooks": {
            "SessionStart": [handler(8)],
            "UserPromptSubmit": [handler(20)],
            "PostToolUse": [handler(8, "Bash|Edit|Write|NotebookEdit")],
            "PostToolUseFailure": [handler(8, "Bash|Edit|Write|NotebookEdit")],
